class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    // Use MultiProvider if you have more services/providers later.
    // For now, ChangeNotifierProvider for AuthService is sufficient.
    return ChangeNotifierProvider<AuthService>(
      create: (_) => AuthService(), // Create an instance of AuthService
      child: MaterialApp(
        title: 'CheckMate', // Your application title
        theme: ThemeData(
          // Define your app's theme
          primarySwatch: Colors.blue, // Example primary color
          visualDensity: VisualDensity.adaptivePlatformDensity,
          // Define input decoration theme for consistent text fields
          inputDecorationTheme: const InputDecorationTheme(
            border: OutlineInputBorder(
              borderRadius: BorderRadius.all(Radius.circular(8.0)),
            ),
            contentPadding: EdgeInsets.symmetric(vertical: 14.0, horizontal: 12.0),
          ),
          // Define button themes for consistency
          elevatedButtonTheme: ElevatedButtonThemeData(
            style: ElevatedButton.styleFrom(
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(8.0),
              ),
              padding: const EdgeInsets.symmetric(vertical: 14.0, horizontal: 20.0),
              textStyle: const TextStyle(fontSize: 16, fontWeight: FontWeight.w500),
            ),
          ),
          textButtonTheme: TextButtonThemeData(
            style: TextButton.styleFrom(
               textStyle: const TextStyle(fontSize: 14),
            ),
          ),
          // Add other theme customizations as needed
        ),
        // Start with the Wrapper widget
        // The Wrapper will listen to auth state and show WelcomeScreen or the appropriate Dashboard
        home: const Wrapper(),
        debugShowCheckedModeBanner: false, // Hide debug banner
      ),
    );
  }
}
